import { Context, Effect, Layer, Option, Schema } from "effect";

export class R2UploadError extends Schema.TaggedError<R2UploadError>()("R2UploadError", {
  cause: Schema.Unknown,
}) {}
export class R2ReadError extends Schema.TaggedError<R2ReadError>()("R2ReadError", {
  cause: Schema.Unknown,
}) {}
export class R2DeleteError extends Schema.TaggedError<R2DeleteError>()("R2DeleteError", {
  cause: Schema.Unknown,
}) {}

/*
 * The one way this app reaches object storage. Keys are always generated by the
 * server: a map archive key is a validated `maps/<name>.pmtiles`, and a listing
 * photo key is a random id under the listing it belongs to. No request carries a
 * key and nothing ever lists the bucket.
 */
export interface StorageRepository {
  readonly put: (
    key: string,
    value: ReadableStream | ArrayBuffer | ArrayBufferView | string,
  ) => Effect.Effect<R2Object, R2UploadError>;
  /*
   * A single object read. `range` is the request's `Range` header verbatim (or
   * undefined), handed to R2 so the runtime answers with the slice and reports
   * it in `object.range`; the Worker never does byte arithmetic itself. A
   * missing key is `None`, not an error.
   */
  readonly get: (
    key: string,
    range: string | undefined,
  ) => Effect.Effect<Option.Option<R2ObjectBody>, R2ReadError>;
  readonly delete: (key: string) => Effect.Effect<void, R2DeleteError>;
}

export const StorageRepository = Context.Service<StorageRepository>("StorageRepository");

export const StorageRepositoryLive = (bucket: R2Bucket) =>
  Layer.effect(
    StorageRepository,
    Effect.succeed({
      put: (key, value) =>
        Effect.tryPromise({
          try: () => bucket.put(key, value),
          catch: (e) => new R2UploadError({ cause: e }),
        }).pipe(
          Effect.filterOrFail(
            (result) => !!result,
            () => new R2UploadError({ cause: "Preconditions Failed" }),
          ),
        ),
      get: (key, range) =>
        Effect.tryPromise({
          try: () =>
            bucket.get(
              key,
              range === undefined ? undefined : { range: new Headers({ Range: range }) },
            ),
          catch: (e) => new R2ReadError({ cause: e }),
        }).pipe(Effect.map(Option.fromNullishOr)),
      delete: (key) =>
        Effect.tryPromise({
          try: () => bucket.delete(key),
          catch: (e) => new R2DeleteError({ cause: e }),
        }),
    }),
  );
